fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cols: i32 = 32;
    let cw: i32 = w / cols;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 999);
        host::display::state_set(2, 0);
        host::display::state_set(3, 0);
    }
    let mut gx: i32 = host::display::state_get(2);
    let mut gy: i32 = host::display::state_get(3);
    if gy == 0 {
        let seed: i32 = host::display::state_get(1) * 1103515245 + 12345;
        host::display::state_set(1, seed);
        gx = (seed >> 16) & 31;
        gy = 1;
    }
    let stack: i32 = host::display::state_get(8 + gx);
    let top: i32 = h - 4 - stack * 4;
    gy = gy + 6;
    if gy >= top {
        host::display::state_set(8 + gx, stack + 1);
        if (stack + 1) * 4 > h - 12 {
            let mut k: i32 = 0;
            while k < cols {
                host::display::state_set(8 + k, 0);
                k = k + 1;
            }
        }
        gy = 0;
    }
    host::display::state_set(2, gx);
    host::display::state_set(3, gy);
    host::display::clear(0x000000);
    let mut i: i32 = 0;
    while i < cols {
        let sh: i32 = host::display::state_get(8 + i) * 4;
        host::display::fill_rect(i * cw, h - sh, cw - 1, sh, 0xd0b040);
        i = i + 1;
    }
    if gy > 0 {
        host::display::fill_rect(gx * cw + cw / 2 - 2, gy, 4, 4, 0xffffff);
    }
    host::display::present();
}
